#[test]
fn fixes_from_100_match_vanilla() {
    let mut failures = 0;
    for &(ty, from, to, input, expected) in CASES_FROM_100 {
        let actual = update(ty, from, to, input);
        if actual != expected {
            failures += 1;
            eprintln!("{ty} {from} -> {to}: {input}\n  expected {expected}\n  actual   {actual}");
        }
    }
    assert_eq!(failures, 0);
}

