#[test]
fn fixes_from_2000_match_vanilla() {
    for &(ty, from, to, input, expected) in CASES_FROM_2000 {
        assert_eq!(update(ty, from, to, input), expected, "{ty} {from} -> {to}: {input}");
    }
}

#[test]
#[should_panic(expected = "Unable load old custom worlds.")]
fn old_custom_worlds_are_rejected_like_vanilla() {
    update("world_gen_settings", 2832, 2833, r#"{dimensions:{"minecraft:overworld":{generator:{type:"minecraft:debug"}}},seed:5L}"#);
}
